    throw new Error("P0路径runtime行数与receipt不一致");
  }
  const codes = new Set();
  const identities = new Set();
  for (const row of runtimeRows) {
    const code = String(row.ts_code || "");
    const identity = `${signalDate}|${code}|${row.stage_transition}`;
    const rank = finiteNumber(row.promotion_rank);
    const selected = finiteNumber(row.top10_selected);
    if (
      !code || codes.has(code) || identities.has(row.identity) ||
      row.signal_date !== signalDate || row.identity !== identity ||
      !["2→3", "3→4"].includes(row.stage_transition) ||
      row.feature_snapshot_sha256 !== contract.feature_snapshot_sha256 ||
      !Number.isInteger(rank) || rank < 1 || rank > runtimeRows.length ||
      ![0, 1].includes(selected)
