    throw new Error("P0路径runtime晋级排名不是完整1..N");
  }
  const identityPayload = {
    schema: "dc20_primary_d_runtime_identity_v1",
    signal_date: signalDate,
    rows: [...runtimeRows].sort((left, right) => left.ts_code.localeCompare(right.ts_code)).map(row => ({
      identity: row.identity,
      ts_code: row.ts_code,
      stage_transition: row.stage_transition,
      top10_selected: Number(row.top10_selected),
      promotion_rank: Number(row.promotion_rank)
