  }
  const selectedRows = runtimeRows
    .filter(row => Number(row.top10_selected) === 1)
    .sort((left, right) => Number(left.promotion_rank) - Number(right.promotion_rank));
  if (
    selectedRows.length !== contract.rows.length ||
    selectedRows.some((row, index) =>
      row.ts_code !== contract.rows[index].ts_code ||
      Number(row.promotion_rank) !== contract.rows[index].promotion_rank ||
      row.stage_transition !== contract.rows[index].stage_transition
    )
  ) throw new Error("P0路径runtime与冻结TopN成员或晋级顺序不一致");

  const pathRows = selectedRows.map(row => {
    const code = String(row.path_label_code || "");
    const label = String(row.path_label || "");
    const explanation = String(row.path_explanation || "").trim();
    const daysObserved = finiteNumber(row.path_days_observed);
    const coverage = finiteNumber(row.path_data_coverage);
    const latestStrength = finiteNumber(row.path_strength_latest);
    const strengthDelta = finiteNumber(row.path_strength_delta);
    if (!(code in PRIMARY_PATH_LABELS) || label !== PRIMARY_PATH_LABELS[code] || !explanation) {
      throw new Error(`P0路径runtime标签合同无效：${row.ts_code}`);
    }
    if (
      daysObserved == null || daysObserved < 0 ||
      coverage == null || coverage < 0 || coverage > 1 ||
      (code !== "INSUFFICIENT" && (daysObserved < 2 || coverage < 0.35 || latestStrength == null || strengthDelta == null))
    ) throw new Error(`P0路径runtime观测证据无效：${row.ts_code}`);
