      ts_code: row.ts_code,
      path_label_code: code,
      path_label: label,
      path_explanation: explanation,
      path_days_observed: daysObserved,
      path_data_coverage: coverage,
      path_strength_latest: latestStrength,
      path_strength_delta: strengthDelta
    };
  });
