    status: "VALID",
    signal_date: signalDate,
    pages_revision_sha: revisionSha,
    runtime_index_path: PRIMARY_D_RUNTIME_INDEX.path,
    runtime_index_sha256: await sha256Hex(indexBytes),
    receipt_path: receiptPath,
    receipt_sha256: runtimeIndex.latest_receipt_sha256,
    runtime_path: runtimePath,
    runtime_sha256: outputs.runtime_features_sha256,
    feature_snapshot_sha256: contract.feature_snapshot_sha256,
    top10_members_sha256: contract.top10_members_sha256,
    rows: pathRows
