// Published P0 receipts are the daily inventory. Old report dates and P1
// availability must never decide whether a promotion list is navigable.
async function loadDailyNavigation() {
  const index = strictJsonFromBytes(await fetchPublishedBytes("outputs/decision/three_rank_history/index.json"), "D日目录");
  executableProfitExpect(index.schema_version === "dc20_three_rank_history_index_v2" && index.data_alias === false
    && index.statistics_url === "outputs/decision/three_rank_history/statistics.json" && isSha256(index.statistics_sha256), "D日目录合同无效");
  const bytes = await fetchPublishedBytes(index.statistics_url);
  executableProfitExpect(await sha256Hex(bytes) === index.statistics_sha256, "D日目录SHA256不一致");
  const records = strictJsonFromBytes(bytes, "D日文件目录")?.p_fill_shadow_top2_forward?.primary_only_non_shadow_records;
  executableProfitExpect(Array.isArray(records), "D日文件目录缺失");
  const seen = new Set();
  for (const entry of records) {
    const d = canonicalYmd(entry.signal_date);
    executableProfitExpect(d && d === entry.signal_date && d >= INDEPENDENCE_CUTOVER_SIGNAL_DATE
      && d < canonicalYmd(entry.exec_date) && entry.exec_date < canonicalYmd(entry.exit_date) && !seen.has(d)
      && ["NATURAL", "RETROSPECTIVE_RECOVERY"].includes(entry.generation_mode)
      && entry.receipt?.path === `outputs/decision/primary_d_receipt_${d}.json`
      && entry.snapshot?.path === `outputs/decision/three_rank_top10_${d}.json`
      && [entry.receipt.sha256, entry.snapshot.sha256, entry.top10_members_sha256].every(isSha256), "D日目录日期、重复项或绑定无效");
    seen.add(d);
  }
  return [...records].sort((a, b) => b.signal_date.localeCompare(a.signal_date));
}

async function refreshDailyNavigation() {
  try {
    state.dailyNavigation = await loadDailyNavigation();
    state.dailyNavigationError = "";
  } catch (error) {
    state.dailyNavigation = [];
    state.dailyNavigationError = `D日目录暂不可用：${error.message || error}`;
  }
  setNavigation();
}

function dailyAdjacentDates() {
  const selected = state.dailyRequestedDate || state.currentThreeRank?.signal_date;
  const dates = [...new Set([...(state.dailyNavigation || []).map(entry => entry.signal_date), state.dailyLatestDate].filter(Boolean))].sort();
  return { previous: dates.filter(d => d < selected).at(-1) || null, next: dates.find(d => d > selected) || null };
}

function setNavigation() {
  if (new URLSearchParams(location.search).get("view") === "research") {
    els.prevBtn.disabled = state.index >= state.reports.length - 1;
    els.nextBtn.disabled = state.index <= 0;
    for (const [button, label] of [[els.prevBtn, "上一份历史报告"], [els.nextBtn, "下一份报告"]]) {
      button.title = label;
      button.setAttribute("aria-label", label);
    }
    return;
  }
  const dates = dailyAdjacentDates();
  for (const [button, date, label] of [[els.prevBtn, dates.previous, "上一交易日名单"], [els.nextBtn, dates.next, "下一交易日名单"]]) {
    button.disabled = !date;
    button.title = state.dailyNavigationError || (date ? `${label} · D ${dateText(date)}` : `没有${label}`);
    button.setAttribute("aria-label", button.title);
  }
}

function navigateDaily(direction) {
  if (new URLSearchParams(location.search).get("view") === "research") {
    return loadReport(state.index + direction).catch(showError);
  }
  const dates = dailyAdjacentDates();
  const date = direction > 0 ? dates.previous : dates.next;
  if (!date) return;
  const url = new URL(window.location.href);
  url.searchParams.delete("page");
  url.searchParams.set("d", date); // Keep the exact target even if the inventory lags the latest pointer.
  url.hash = "";
  window.location.assign(url.toString()); // A fresh state prevents cross-D async races.
}

async function loadPublishedDailyEntry(entry) {
  const receiptBytes = await fetchPublishedBytes(entry.receipt.path);
  executableProfitExpect(await sha256Hex(receiptBytes) === entry.receipt.sha256, "历史D receipt SHA256不一致");
