  const cal = receipt.inputs?.calendar;
  executableProfitExpect(cal?.path === "data/market/trade_cal_sse.csv" && cal.exchange === "SSE" && cal.signal_date_is_open === true && isSha256(cal.sha256), "历史D交易日历绑定缺失");
  const [jsonBytes, csvBytes, calendarBytes] = await Promise.all([fetchPublishedBytes(o.json_path), fetchPublishedBytes(o.csv_path), fetchPublishedBytes(cal.path)]);
  executableProfitExpect(await sha256Hex(jsonBytes) === o.json_sha256 && await sha256Hex(csvBytes) === o.csv_sha256
    && await sha256Hex(calendarBytes) === cal.sha256, "历史D名单或交易日历SHA256不一致");
  const sessions = parseStrictCsvBytes(calendarBytes, ["exchange", "cal_date", "is_open"], "SSE交易日历").filter(row => row.exchange === "SSE");
  executableProfitExpect(sessions.every(row => canonicalYmd(row.cal_date) === row.cal_date && ["0", "1"].includes(row.is_open))
    && new Set(sessions.map(row => row.cal_date)).size === sessions.length, "SSE交易日历存在无效或重复日期");
  const openDates = sessions.filter(row => row.is_open === "1").map(row => row.cal_date).sort();
  const position = openDates.indexOf(entry.signal_date);
  executableProfitExpect(position >= 0 && openDates[position + 1] === entry.exec_date && openDates[position + 2] === entry.exit_date, "历史D/T/T+1不是连续SSE交易日");
  const wrapper = { signal_date: entry.signal_date, exec_date: entry.exec_date, exit_date: entry.exit_date,
