  const contract = validatedThreeRankContract(wrapper);
  executableProfitExpect(contract && contract.bundle_sha256 === o.bundle_sha256 && contract.feature_snapshot_sha256 === o.feature_snapshot_sha256
    && contract.top10_members_sha256 === o.top10_members_sha256 && contract.downloads?.csv_sha256 === o.csv_sha256
    && contract.promotion_pool_size === o.promotion_pool_size && contract.top10_count === o.top10_count, "历史D冻结合同与receipt不一致");
  const runtimeIndex = { schema_version: PRIMARY_D_RUNTIME_INDEX.schema, index_kind: PRIMARY_D_RUNTIME_INDEX.kind, data_alias: false,
    latest_signal_date: entry.signal_date, latest_exec_date: entry.exec_date, latest_exit_date: entry.exit_date,
    latest_receipt_url: entry.receipt.path, latest_receipt_sha256: entry.receipt.sha256,
    latest_runtime_features_url: o.runtime_features_path, latest_runtime_features_sha256: o.runtime_features_sha256,
    runtime_feature_row_count: o.runtime_feature_row_count, runtime_selected_count: o.runtime_selected_count, runtime_identity_sha256: o.runtime_identity_sha256,
    latest_feature_snapshot_sha256: o.feature_snapshot_sha256, latest_top10_members_sha256: o.top10_members_sha256,
    latest_three_rank_json_url: o.json_path, latest_three_rank_json_sha256: o.json_sha256,
    latest_three_rank_csv_url: o.csv_path, latest_three_rank_csv_sha256: o.csv_sha256, latest_bundle_sha256: o.bundle_sha256 };
  return { wrapper, runtimeIndex };
}

async function loadDailyHistoricalProfit(currentThreeRank) {
  const entry = state.currentPrimaryMixedDailyTop2?.status === "ready"
    && state.currentPrimaryMixedDailyTop2.index.entries.find(row => row.signal_date === currentThreeRank.signal_date);
  executableProfitExpect(entry, "该D日盈利文件尚未通过目录校验；晋级名单保留");
  const [jsonBytes, csvBytes] = await Promise.all([fetchPublishedBytes(entry.projection_json_url), fetchPublishedBytes(entry.projection_csv_url)]);
  executableProfitExpect(await sha256Hex(jsonBytes) === entry.projection_json_sha256 && await sha256Hex(csvBytes) === entry.projection_csv_sha256, "历史盈利文件SHA256不一致");
  const p = strictJsonFromBytes(jsonBytes, "历史盈利排序");
  const index = { schema_version: PRIMARY_MIXED_PROFIT_INDEX_SCHEMA, index_kind: "dated_primary_profit_research_pointer_only", data_alias: false,
    display_name: "混合盈利排序", status: p.status, generation_mode: entry.generation_mode, prospective: entry.prospective, retrospective_non_forward: entry.retrospective_non_forward,
    latest_signal_date: entry.signal_date, latest_exec_date: entry.exec_date, latest_exit_date: entry.exit_date,
    latest_projection_json_url: entry.projection_json_url, latest_projection_json_sha256: entry.projection_json_sha256,
    latest_projection_csv_url: entry.projection_csv_url, latest_projection_csv_sha256: entry.projection_csv_sha256,
    latest_projection_snapshot_sha256: entry.projection_snapshot_sha256, latest_top10_members_sha256: entry.top10_members_sha256,
    latest_source_bundle_sha256: entry.source_bundle_sha256, latest_source_feature_snapshot_sha256: entry.source_feature_snapshot_sha256,
    candidate_count: entry.candidate_count, source_bindings: p.source_bindings, boundaries: p.boundaries };
  validatePrimaryProfitIndex(index, PRIMARY_MIXED_PROFIT_INDEX_SCHEMA, EXECUTABLE_PROFIT_RESEARCH_ROOT, "混合盈利排序");
  const projection = await validatePrimaryMixedProfitProjection(p, index, currentThreeRank);
  executableProfitExpect(entry.rows.length === Math.min(2, projection.rows.length) && entry.rows.every((row, i) =>
    row.slot === i + 1 && row.ts_code === projection.rows[i].ts_code && row.name === projection.rows[i].name
    && row.industry === projection.rows[i].industry && row.stage_transition === projection.rows[i].stage_transition
    && row.promotion_rank === projection.rows[i].promotion_rank && row.mixed_profit_rank === projection.rows[i].executable_profit_research_rank), "历史盈利前二与同D冻结排名不一致");
  return { status: "ready", kind: "primary_core", index, projection, statistics: null, shadow: null, shadowError: "历史D只展示当日排名，不混入最新累计" };
}

async function initializeDailyHistory(date) {
  executableProfitExpect(/^20\d{6}$/.test(date) && canonicalYmd(date) === date, "历史D参数无效");
  state.dailyNavigation = await loadDailyNavigation();
  state.dailyLatestDate = null; // A catalog maximum is not proof of the live latest D.
  const entry = state.dailyNavigation.find(row => row.signal_date === date);
  executableProfitExpect(entry, `没有已发布且可校验的 D ${dateText(date)} 名单；不会回退到最新日`);
  const loaded = await loadPublishedDailyEntry(entry);
  state.currentThreeRank = loaded.wrapper;
  state.index = 0; // Independent P0/P1 renderer; never an old report-index position.
  try { state.currentThreeRankPathEvidence = await loadCurrentThreeRankPathEvidence(loaded.wrapper, loaded.runtimeIndex); }
  catch (error) { state.currentThreeRankPathEvidence = { status: "INVALID", signal_date: date, error: String(error.message || error) }; }
  await refreshPublicObservationStatistics();
  await refreshCurrentThreeRankTTruth(loaded.wrapper);
  await refreshCurrentPrimaryMixedDailyTop2();
  try { state.currentExecutableProfitResearch = await loadDailyHistoricalProfit(loaded.wrapper); }
  catch (error) { state.currentExecutableProfitResearch = { status: "invalid", message: String(error.message || error) }; }
  renderPrimaryCoreOnly(new Error("历史D日只读名单，不加载旧Action"));
  els.footer.textContent = `DC2.0 · 历史 D ${dateText(date)} · ${entry.generation_mode === "NATURAL" ? "自然生成留档" : "恢复留档，不计前向"} · T/T+1只展示同日已验证数据`;
}
